insert into public.actors (id, name, stage_name, tagline, birthdate, hometown, network, agency, generation, gender, decades, genres, base_fans, bio, photo_url, photo_credit, photo_source, wiki_title, socials, spotlight, trending_rank, created_by) values
  ('vilma-santos', 'Vilma Santos', '', 'Child star turned box-office queen, and Governor of Batangas', '1953-11-03', 'Manila', 'Independent', '', 'Legends', 'Female', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Period']::text[], 0, 'Vilma Santos began acting as a child in the 1960s and became one of the biggest box-office draws of the 1970s and early 1980s. Her honors include thirteen FAMAS Awards, eleven Gawad Urian and five Luna Awards, for films such as Relasyon, Sister Stella L. and Dekada ''70. Alongside acting she built a long career in public service: Mayor of Lipa (1998–2007), Governor of Batangas (2007–2016), representative of Batangas'' 6th district (2016–2022) and, since 2025, Governor of Batangas once more.', '/seed/actors/vilma-santos.jpg', 'Littlebeatlebum · CC BY-SA 4.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Governor_Vilma_Santos-Recto.jpg', 'Vilma_Santos', '{}'::jsonb, true, 11, null),
  ('sharon-cuneta', 'Sharon Cuneta', 'Megastar', 'The Megastar: million-selling singer and blockbuster leading lady', '1966-01-06', 'Santa Mesa, Manila', 'ABS-CBN', '', 'Legends', 'Female', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Comedy']::text[], 0, 'Sharon Cuneta rose to fame as a recording artist with the 1978 single "Tawag ng Pag-ibig" and the hit "Mr. DJ", and is one of the best-selling Filipino musicians of all time. She made her film debut opposite Gabby Concepcion in Dear Heart (1981), followed by blockbusters such as Bituing Walang Ningning (1985), Madrasta (1996) and Crying Ladies (2003). Her accolades include three FAMAS Awards, a Gawad Urian and nineteen Box Office Entertainment Awards.', '/seed/actors/sharon-cuneta.jpg', 'ChasterJohn Luna · CC BY 3.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Sharon_Cuneta_performing_%22Love_Again%22_in_2019.jpg', 'Sharon_Cuneta', '{}'::jsonb, false, 12, null),
  ('christopher-de-leon', 'Christopher de Leon', 'Boyet', 'The King of Philippine Drama, a leading man for five decades', '1956-10-31', 'Manila', 'Independent', '', 'Legends', 'Male', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Period', 'Romance']::text[], 0, 'Christopher de Leon won the FAMAS Award for Best Actor for his very first film, Lino Brocka''s Tinimbang Ka Ngunit Kulang (1974), and a second for Eddie Romero''s Ganito Kami Noon... Paano Kayo Ngayon? (1976). Often called the "King of Philippine Drama", he has led period, romance and thriller productions for more than five decades, from Ikaw ay Akin (1978) to Dekada ''70 (2002). He is in the Best Actor Hall of Fame of both the FAMAS Awards (1993) and the Metro Manila Film Festival (2019).', '/seed/actors/christopher-de-leon.jpg', 'Rated Korina · CC BY 3.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Boyet_Interview.jpg', 'Christopher_de_Leon', '{}'::jsonb, false, null, null),
  ('maricel-soriano', 'Maricel Soriano', 'The Diamond Star', 'The Diamond Star, from child actress to drama and comedy icon', '1965-02-25', 'Pasay', 'Independent', '', 'Legends', 'Female', array['1980s', '1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Comedy']::text[], 0, 'Maricel Soriano debuted as a child in My Heart Belongs to Daddy (1971) and played Shirley Puruntong in John en Marsha, the longest-running Philippine sitcom. Launched as one of the first Regal Babies, she headlined 1980s hits such as Inday Bote (1985) and kept television audiences through her weekly drama anthologies. Known as "The Diamond Star", she has won two Asian Television Awards, five FAMAS Awards and four Luna Awards.', '/seed/actors/maricel-soriano.jpg', 'Film Development Council of the Philippines · Public domain · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Maricel_Soriano_-_Parangal_ng_Sining_2023_(cropped).jpg', 'Maricel_Soriano', '{}'::jsonb, false, null, null),
  ('piolo-pascual', 'Piolo Pascual', 'Papa P', 'Heartthrob, action star and the producer behind Kita Kita', '1977-01-12', 'Manila', 'ABS-CBN', '', 'Millennial', 'Male', array['1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Action', 'Fantasy']::text[], 0, 'Piolo Pascual got his start with a bit part in The Vizconde Massacre Story (1993) and on the youth variety show That''s Entertainment, then rose to fame opposite Judy Ann Santos in the 1997 soap opera Esperanza. His turn in the period film Dekada ''70 (2002) won Best Supporting Actor at the FAMAS, Gawad Urian and PMPC Star Awards. He top-billed the supernatural series Lobo (2008), starred in the Cannes-screened thriller On the Job (2013), and produced the Kimmy Dora films and Kita Kita (2017).', '/seed/actors/piolo-pascual.jpg', 'Gerry Edra · CC BY 3.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Piolo_Pascual_at_the_Star_Magic_Concert_Tour_in_Ontario,_CA,_June_2009.jpg', 'Piolo_Pascual', '{}'::jsonb, false, null, null),
  ('coco-martin', 'Coco Martin', 'Ultimate Superstar', 'From indie breakout to the star of FPJ''s Ang Probinsyano', '1981-11-01', 'Santa Cruz, Manila', 'ABS-CBN', '', 'Millennial', 'Male', array['2000s', '2010s', '2020s']::text[], array['Action', 'Drama', 'Fantasy']::text[], 0, 'Coco Martin broke through in acclaimed independent films such as Serbis, Kinatay and Jay, winning Best Supporting Actor at the Gawad Urian for the last. He moved into primetime with Tayong Dalawa (2009) and Juan dela Cruz (2013), then became a superstar as Cardo Dalisay in FPJ''s Ang Probinsyano (2015–2022), the second longest-running drama series on Philippine television, followed by FPJ''s Batang Quiapo (2023). Named Actor of the Decade (2000–2009) at the Gawad Urian, he also directs and produces through CCM Film Productions.', '/seed/actors/coco-martin.jpg', 'SwarmCheng · CC BY-SA 4.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Floats_of_the_48th_Metro_Manila_Film_Festival_Festival_Parade_of_Stars_27.jpg', 'Coco_Martin', '{}'::jsonb, true, 3, null),
  ('marian-rivera', 'Marian Rivera', 'Primetime Queen', 'Kapuso Primetime Queen, from Marimar to Best Actress for Balota', '1984-08-12', 'Madrid, Spain', 'GMA', '', 'Millennial', 'Female', array['2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Fantasy']::text[], 0, 'Born in Madrid, Marian Rivera began as a commercial model and made her film debut in Enteng Kabisote 2 (2005). She rose to stardom in the 2007 remake of Marimar, then led fantasy and drama hits such as Dyesebel (2008), Darna (2009) and Amaya (2011). Her films as a lead have grossed more than ₱1.9 billion, and her role as a teacher in the political thriller Balota (2024) won Best Actress at Cinemalaya and the FAMAS Awards.', '/seed/actors/marian-rivera.jpg', 'Malacañang Photo Bureau/Robert Viñas · Public domain · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Marian_Rivera_-_2014_(cropped).jpg', 'Marian_Rivera', '{}'::jsonb, true, 4, null),
  ('dingdong-dantes', 'Dingdong Dantes', '', 'Leading man, Family Feud host and producer of Rewind', '1980-08-02', 'Quezon City', 'GMA', '', 'Millennial', 'Male', array['2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Fantasy']::text[], 0, 'Dingdong Dantes gained prominence in the early 2000s in dramas such as Sana ay Ikaw na Nga (2001) and Twin Hearts (2004), and wider fame opposite Marian Rivera in Marimar (2007). He has hosted StarStruck, Family Feud and Amazing Earth, and produces films through AgostoDos Pictures, including Tiktik: The Aswang Chronicles (2012) and Rewind (2023), which became the highest-grossing film in the Philippines. He married Rivera in 2014.', '/seed/actors/dingdong-dantes.jpg', 'Malacañang Photo Bureau/Robert Viñas · Public domain · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Dingdong_Dantes_-_2014_(cropped).jpg', 'Dingdong_Dantes', '{}'::jsonb, false, 7, null),
  ('anne-curtis', 'Anne Curtis', '', 'Actress, It''s Showtime host and UNICEF national ambassador', '1985-02-17', 'Yarrawonga, Victoria, Australia', 'Viva', 'Viva Artists Agency', 'Millennial', 'Female', array['1990s', '2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Comedy']::text[], 0, 'Anne Curtis made her film debut at twelve in Magic Kingdom: Ang Alamat ng Damortis (1997) and broke through as a disfigured woman in Kampanerang Kuba (2005). She won the Metro Manila Film Festival Best Actress award for Baler (2008) and the FAMAS Best Actress award for No Other Woman (2011), which became the highest-grossing Filipino film at the time. A co-host of It''s Showtime since 2009, she has served as UNICEF''s national ambassador in the Philippines since 2019.', '/seed/actors/anne-curtis.jpg', 'George Parrilla · CC BY 2.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Anne_Curtis,_2009_(cropped).jpg', 'Anne_Curtis', '{}'::jsonb, false, 8, null),
  ('kathryn-bernardo', 'Kathryn Bernardo', '', 'Star of three of the highest-grossing Filipino films ever', '1996-03-26', 'Cabanatuan, Nueva Ecija', 'ABS-CBN', 'Star Magic', 'Millennial', 'Female', array['2000s', '2010s', '2020s']::text[], array['Drama', 'Romance', 'Comedy']::text[], 0, 'Born in Cabanatuan, Kathryn Bernardo began as a child actress and rose to prominence as one of the title characters in Mara Clara (2010). Princess and I (2012) began her long screen partnership with Daniel Padilla. She has starred in three of the highest-grossing Filipino films of all time, The Hows of Us (2018), Hello, Love, Goodbye (2019) and Hello, Love, Again (2024), and won the FAMAS Award for Best Actress for the black comedy A Very Good Girl (2023).', '/seed/actors/kathryn-bernardo.jpg', 'Patrick Cristiano · CC BY-SA 4.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Kathryn_Bernardo_in_2025_(cropped).jpg', 'Kathryn_Bernardo', '{}'::jsonb, true, 1, null),
  ('daniel-padilla', 'Daniel Padilla', '', 'Singer-actor behind Barcelona and The Hows of Us', '1995-04-26', 'Manila', 'ABS-CBN', 'Star Magic', 'Millennial', 'Male', array['2010s', '2020s']::text[], array['Romance', 'Drama', 'Fantasy']::text[], 0, 'Daniel Padilla debuted in the soap opera Gimik 2010 (2010) and landed his first lead in Growing Up (2011). With Kathryn Bernardo he starred in hit series such as Princess and I, Got to Believe and La Luna Sangre, and films including She''s Dating the Gangster (2014), Barcelona: A Love Untold (2016) and The Hows of Us (2018). His films have earned ₱3.14 billion at the box office, and as a singer he has released several double-platinum albums.', '/seed/actors/daniel-padilla.jpg', 'Faty Bhojara · CC BY-SA 3.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Daniel_Padilla_at_Celebrate_Mega_in_Iceland_2016_(6).jpg', 'Daniel_Padilla', '{}'::jsonb, false, 9, null),
  ('alden-richards', 'Alden Richards', 'Asia''s Multimedia Star', 'Kapuso leading man, from AlDub to Hello, Love, Again', '1992-01-02', 'Quezon City', 'GMA', 'Sparkle GMA Artist Center', 'Millennial', 'Male', array['2010s', '2020s']::text[], array['Romance', 'Drama', 'Period', 'Action']::text[], 0, 'Alden Richards made his screen debut in the fantasy series Alakdana (2011) and broke through in the romantic drama One True Love (2012). He became a phenomenon in the Kalyeserye segment opposite Maine Mendoza, known as AlDub, and went on to play José Rizal in Ilustrado (2014) and star in Pulang Araw (2024). Hello, Love, Goodbye (2019) and Hello, Love, Again (2024) rank among the highest-grossing Filipino films of all time, and he made his directing debut with Out of Order (2025).', '/seed/actors/alden-richards.jpg', 'JmKissme · CC BY-SA 3.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Alden_Richards_at_the_OMG_Awards.jpg', 'Alden_Richards', '{}'::jsonb, true, 2, null),
  ('liza-soberano', 'Liza Soberano', '', 'Forevermore star who took her career to Hollywood', '1998-01-04', 'Santa Clara, California, U.S.', 'Independent', '', 'Gen Z', 'Female', array['2010s', '2020s']::text[], array['Romance', 'Drama', 'Comedy', 'Horror']::text[], 0, 'Born in Santa Clara, California, Liza Soberano moved to Quezon City and began modelling at thirteen. After her debut in the anthology Wansapanataym (2011), she broke through as the strawberry farmer Agnes in Forevermore (2014), the first of her pairings with Enrique Gil, and was named Box Office Queen for My Ex and Whys (2017). She voiced Alexandra Trese in the animated series Trese (2021) and, after returning to California, appeared in the horror comedy Lisa Frankenstein (2024).', '/seed/actors/liza-soberano.jpg', 'Embassy of the United States, Manila / Ambassador Lee Lipton · Public domain · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Liza_Soberano_in_2026.jpg', 'Liza_Soberano', '{}'::jsonb, false, null, null),
  ('donny-pangilinan', 'Donny Pangilinan', '', 'Myx VJ turned leading man of He''s Into Her and Can''t Buy Me Love', '1998-02-10', 'Manila', 'ABS-CBN', 'Star Magic', 'Gen Z', 'Male', array['2010s', '2020s']::text[], array['Romance', 'Comedy', 'Drama']::text[], 0, 'Donny Pangilinan started out in 2016 as a video jockey on the music channel Myx and made his film debut in Regal Films'' Walwal (2018). He has since led a string of Star Cinema productions, most notably James & Pat & Dave (2020), the series He''s Into Her (2021) and the teleserye Can''t Buy Me Love (2023–2024). He also records music under Universal Records.', '/seed/actors/donny-pangilinan.jpg', 'Patrick Cristiano · CC BY-SA 4.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Donny_Pangilinan.jpg', 'Donny_Pangilinan', '{}'::jsonb, false, 6, null),
  ('barbie-forteza', 'Barbie Forteza', 'Kapuso Primetime Princess', 'Maria Clara at Ibarra star and Fantasporto Best Actress', '1997-07-31', 'Biñan, Laguna', 'GMA', 'Sparkle GMA Artist Center', 'Gen Z', 'Female', array['2000s', '2010s', '2020s']::text[], array['Drama', 'Period', 'Romance']::text[], 0, 'Barbie Forteza won Best Supporting Actress at the 10th Cinemalaya festival for playing a shoemaker''s daughter in Mariquina (2014), and Best Actress at Portugal''s Fantasporto festival for the sea-gypsy drama Laut (2016). On television she led The Half Sisters (2014) and gained wider recognition with Maria Clara at Ibarra (2022), Maging Sino Ka Man (2023) and the war drama Pulang Araw (2024). In 2017 the National Commission for Culture and the Arts gave her an Ani ng Dangal award.', '/seed/actors/barbie-forteza.jpg', 'Chareze Stamatelaky from Sta. Rosa, Philippines · CC BY 2.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Barbie_Forteza.jpg', 'Barbie_Forteza', '{}'::jsonb, false, 10, null),
  ('maris-racal', 'Maris Racal', '', 'Pinoy Big Brother runner-up turned breakout star of Can''t Buy Me Love', '1997-09-22', 'Tagum, Davao del Norte', 'ABS-CBN', '', 'Gen Z', 'Female', array['2010s', '2020s']::text[], array['Drama', 'Romance', 'Action']::text[], 0, 'Maris Racal rose to prominence in 2014 as runner-up of Pinoy Big Brother: All In, then signed with Star Magic and performed with the dance groups Girltrends and BFF5. Her breakthrough came as Irene Tiu in the ABS-CBN romantic drama Can''t Buy Me Love (2023–2024). She led the drama Sunshine (2024), an entry at the 49th Toronto International Film Festival, and joined the action drama series Incognito (2025).', '/seed/actors/maris-racal.jpg', 'Anonnymuz · CC BY 4.0 · Wikimedia Commons (cropped)', 'https://commons.wikimedia.org/wiki/File:Maris_Racal_2024.jpg', 'Maris_Racal', '{}'::jsonb, false, 5, null)
