insert into public.news (id, headline, excerpt, body, source, minutes_read, published_at, image_url, tag, actor_id) values
  ('f1', 'The Hello, Love films and the record books', 'Kathryn Bernardo and Alden Richards share two of the highest-grossing Filipino films of all time.', 'Hello, Love, Goodbye (2019) paired ABS-CBN''s Kathryn Bernardo with GMA''s Alden Richards, stars from rival networks, as a domestic worker and a bartender in Hong Kong. Five years later Hello, Love, Again (2024) reunited them, and both films now rank among the highest-grossing Filipino films ever made.
insert into public.trivia_questions (id, prompt, actor_id, choices, answer_index, fact, position) values
  ('t1', 'He played Cardo Dalisay for seven years in FPJ''s Ang Probinsyano. Who is he?', 'coco-martin', array['Coco Martin', 'Piolo Pascual', 'Dingdong Dantes', 'Daniel Padilla']::text[], 0, 'Coco Martin''s real name is Rodel Nacianceno.', 0),
  ('t2', 'She won FAMAS Best Actress for A Very Good Girl. Name her.', 'kathryn-bernardo', array['Liza Soberano', 'Kathryn Bernardo', 'Barbie Forteza', 'Maris Racal']::text[], 1, 'Kathryn Bernardo was born in Cabanatuan, Nueva Ecija.', 1),
  ('t3', 'This Primetime Queen was born in Madrid. Who is she?', 'marian-rivera', array['Anne Curtis', 'Marian Rivera', 'Maricel Soriano', 'Sharon Cuneta']::text[], 1, 'Marian Rivera rose to stardom in the 2007 remake of Marimar.', 2),
  ('t4', 'Actress, and Governor of Batangas. Who is she?', 'vilma-santos', array['Sharon Cuneta', 'Maricel Soriano', 'Vilma Santos', 'Barbie Forteza']::text[], 2, 'Vilma Santos has won thirteen FAMAS Awards and eleven Gawad Urian.', 3),
  ('t5', 'He won FAMAS Best Actor for his very first film in 1974. Name him.', 'christopher-de-leon', array['Piolo Pascual', 'Christopher de Leon', 'Coco Martin', 'Alden Richards']::text[], 1, 'His debut was Lino Brocka''s Tinimbang Ka Ngunit Kulang.', 4),
  ('t6', 'He played José Rizal in Ilustrado. Who is he?', 'alden-richards', array['Dingdong Dantes', 'Donny Pangilinan', 'Alden Richards', 'Daniel Padilla']::text[], 2, 'Alden Richards is known as Asia''s Multimedia Star.', 5),
  ('t7', 'The "Megastar" who first hit it big with "Mr. DJ". Name her.', 'sharon-cuneta', array['Sharon Cuneta', 'Vilma Santos', 'Anne Curtis', 'Maricel Soriano']::text[], 0, 'Her film debut was Dear Heart (1981).', 6),
  ('t8', 'She won MMFF Best Actress for Baler and co-hosts It''s Showtime. Who is she?', 'anne-curtis', array['Marian Rivera', 'Liza Soberano', 'Kathryn Bernardo', 'Anne Curtis']::text[], 3, 'Anne Curtis was born in Victoria, Australia.', 7),
  ('t9', 'The Diamond Star played Shirley Puruntong in John en Marsha. Name her.', 'maricel-soriano', array['Maricel Soriano', 'Vilma Santos', 'Sharon Cuneta', 'Marian Rivera']::text[], 0, 'John en Marsha is the longest-running Philippine sitcom.', 8),
  ('t10', 'She played María Clara "Klay" in Maria Clara at Ibarra. Who is she?', 'barbie-forteza', array['Maris Racal', 'Barbie Forteza', 'Kathryn Bernardo', 'Liza Soberano']::text[], 1, 'She won Best Actress at Portugal''s Fantasporto festival for Laut.', 9),
  ('t11', 'He rose to fame in Esperanza and later produced Kita Kita. Name him.', 'piolo-pascual', array['Christopher de Leon', 'Coco Martin', 'Piolo Pascual', 'Dingdong Dantes']::text[], 2, 'Piolo Pascual starred in On the Job, which screened at Cannes.', 10),
  ('t12', 'She played Agnes in Forevermore and Taffy in Lisa Frankenstein. Who is she?', 'liza-soberano', array['Liza Soberano', 'Anne Curtis', 'Barbie Forteza', 'Maris Racal']::text[], 0, 'Liza Soberano was born in Santa Clara, California.', 11)
